// implements the interface. Built-in only: reading tool calls out of a
// transcript needs knowledge of that transcript's shape, which an external
// agent's parse-hook does not convey.
func AsToolInvocationScanner(ag Agent) (ToolInvocationScanner, bool) {
	return builtinCapability[ToolInvocationScanner](ag)
}

// AsSessionEndBudgeter returns the agent as SessionEndBudgeter if it implements
// the interface. Built-in only because no external agent needs it yet — not
// because external agents could enforce a budget themselves: a plugin supplies
// only parse-hook, while the work being bounded (endSessionNow, the condense)
// runs in the entire process. Widen DeclaredCaps with a session_end_budget
// field when an external agent has a host that clamps its session-end hook.
func AsSessionEndBudgeter(ag Agent) (SessionEndBudgeter, bool) {
	return builtinCapability[SessionEndBudgeter](ag)
}
package agent

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestRenderAdditionalContextHookOutput(t *testing.T) {
	t.Parallel()

	out, err := RenderAdditionalContextHookOutput("UserPromptSubmit", "use entire trail")
	if err != nil {
		t.Fatalf("RenderAdditionalContextHookOutput: %v", err)
	}
	if !strings.HasSuffix(string(out), "\n") {
		t.Errorf("payload must be newline-terminated, got %q", string(out))
	}

	var parsed struct {
		HookSpecificOutput struct {
			HookEventName     string `json:"hookEventName"`
			AdditionalContext string `json:"additionalContext"`
		} `json:"hookSpecificOutput"`
	}
	if err := json.Unmarshal(out, &parsed); err != nil {
		t.Fatalf("output is not valid JSON: %v (%q)", err, string(out))
	}
	if parsed.HookSpecificOutput.HookEventName != "UserPromptSubmit" {
		t.Errorf("hookEventName = %q, want UserPromptSubmit", parsed.HookSpecificOutput.HookEventName)
	}
	if parsed.HookSpecificOutput.AdditionalContext != "use entire trail" {
		t.Errorf("additionalContext = %q", parsed.HookSpecificOutput.AdditionalContext)
	}
}

func TestRenderAdditionalContextHookOutput_EmptyTextRendersNothing(t *testing.T) {
	t.Parallel()
	for _, text := range []string{"", "   ", "\n\t"} {
		out, err := RenderAdditionalContextHookOutput("BeforeAgent", text)
		if err != nil {
			t.Fatalf("RenderAdditionalContextHookOutput(%q): %v", text, err)
		}
		if len(out) != 0 {
			t.Errorf("empty text %q must render no payload, got %q", text, string(out))
		}
	}
}

